#!/bin/bash
# Mirror's Edge (macOS Apple Silicon / Metal) standalone builder, packager & updater.
#
# Locates your legally owned Mirror's Edge (PC) installation or GOG offline
# installer (using the built-in standalone innoextract binary), fetches/builds
# the native Apple Silicon Metal static-recompilation runtime from source,
# extracts the original game icon, packages a self-contained Mirror's Edge.app
# with your assets inside, ad-hoc signs the bundle, and installs to ~/Downloads
# (or updates an existing Mirror's Edge.app in-place while preserving saves).
#
# No copyrighted game assets or binaries are hosted in the macMirror repo.
# Embedded standalone innoextract v1.9 is licensed under the zlib license
# (see LICENSE.md and Contents/Resources/Licenses/LICENSE.md inside the app).
#
# Usage:
#   quick-install.sh [--dmg] [-g|--game <path>] [--lang <code|all>]
#                    [--local <repo_dir>] [--dest <dir>] [game_files_or_exe]
set -euo pipefail

REPO="${MACMIRROR_REPO:-captain-courageous/macMirror}"
BRANCH="${MACMIRROR_BRANCH:-main}"

APP_NAME="Mirror's Edge"
VOLNAME="Mirror's Edge"
BUNDLE_ID="com.runnermetal.mirrorsedge"
DL="$HOME/Downloads"
SUPPORT_DIR="$HOME/Library/Application Support/Mirror's Edge Native"
TOOLS_DIR="$SUPPORT_DIR/tools"
CACHE_DIR="$SUPPORT_DIR/cache"

# ---------------------------------------------------------------------------
# Terminal UI (degrades cleanly when non-interactive).
# ---------------------------------------------------------------------------
FANCY=no
[ -t 1 ] && [ "${TERM:-dumb}" != "dumb" ] && FANCY=yes || true

if [ "$FANCY" = yes ] && [ "$(tput colors 2>/dev/null || echo 0)" -ge 256 ]; then
	C1=$'\033[38;5;196m' C2=$'\033[38;5;160m' C3=$'\033[38;5;255m'
	AMBER=$'\033[38;5;214m' CYAN=$'\033[38;5;45m'
	GREEN=$'\033[38;5;84m' RED=$'\033[38;5;203m'
	BOLD=$'\033[1m' DIM=$'\033[2m' RESET=$'\033[0m'
elif [ "$FANCY" = yes ]; then
	C1=$'\033[91m' C2=$'\033[31m' C3=$'\033[97m'
	AMBER=$'\033[93m' CYAN=$'\033[96m'
	GREEN=$'\033[92m' RED=$'\033[91m'
	BOLD=$'\033[1m' DIM=$'\033[2m' RESET=$'\033[0m'
else
	C1= C2= C3= AMBER= CYAN= GREEN= RED= BOLD= DIM= RESET=
fi

SPIN=('⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏')
BAR_WIDTH=24

banner() {
	printf '\n'
	printf '  %s██▄ ▄██╗██╗████╗ ████╗  ████╗ ████╗ █╗█████╗  █████╗█████╗  █████╗ █████╗%s\n' "$C1" "$RESET"
	printf '  %s███████║██║██╔██╗██╔██╗██╔═██╗██╔██╗╝██╔═══╝  ██╔══╝██╔═██╗██╔═══╝ ██╔══╝%s\n' "$C1" "$RESET"
	printf '  %s██╔█╔██║██║████╔╝████╔╝██║ ██║████╔╝ ██████╗  ████╗ ██║ ██║██║ ███╗████╗%s\n' "$C2" "$RESET"
	printf '  %s██║ ╚██║██║██╔██╗██╔██╗██║ ██║██╔██╗ ╚════██╗ ██╔══╝ ██║ ██║██║  ██║██╔══╝%s\n' "$C2" "$RESET"
	printf '  %s██║  ██║██║██║██║██║██║╚████╔╝██║██║ ██████╔╝ █████╗█████╔╝╚█████╔╝█████╗%s\n' "$C3" "$RESET"
	printf '  %s╚═╝  ╚═╝╚═╝╚═╝╚═╝╚═╝╚═╝ ╚═══╝ ╚═╝╚═╝ ╚═════╝  ╚════╝╚════╝  ╚════╝ ╚════╝%s\n' "$C3" "$RESET"
	printf '\n'
	printf "  %sMirror's Edge · Native Metal · Apple Silicon%s\n" "$DIM" "$RESET"
	printf '\n'
}

STEPS_TOTAL=5
STEP=0
step() {
	STEP=$((STEP + 1))
	printf '\n%s◆%s %s[%d/%d]%s %s\n' "$C1" "$RESET" "$BOLD" "$STEP" "$STEPS_TOTAL" "$RESET" "$1"
}
ok() { printf '  %s✔%s %s\n' "$GREEN" "$RESET" "$1"; }
warn() { printf '  %s!%s %s\n' "$AMBER" "$RESET" "$1"; }
die() {
	printf '  %s✘ error:%s %s\n' "$RED" "$RESET" "$1" >&2
	shift
	local line
	for line in "$@"; do printf '    %s\n' "$line" >&2; done
	exit 1
}

hsize() {
	awk -v b="${1:-0}" 'BEGIN {
		u[1]="B"; u[2]="KB"; u[3]="MB"; u[4]="GB"; i=1
		while (b >= 1024 && i < 4) { b /= 1024; i++ }
		if (i == 1) printf "%d %s", b, u[i]; else printf "%.1f %s", b, u[i]
	}'
}
file_bytes() { stat -f%z "$1" 2>/dev/null || echo 0; }
du_bytes() {
	local kb
	kb=$(du -skL "$1" 2>/dev/null | awk 'NR==1 {print $1}')
	echo $(( ${kb:-0} * 1024 ))
}

draw_bar() {
	local glyph=$1 label=$2 cur=$3 total=$4
	local pct=0 filled=0 bar='' j=0 tdisp='?'
	if [ "$total" -gt 0 ]; then
		pct=$((cur * 100 / total))
		[ "$pct" -gt 100 ] && pct=100
		tdisp=$(hsize "$total")
	fi
	filled=$((pct * BAR_WIDTH / 100))
	while [ "$j" -lt "$BAR_WIDTH" ]; do
		if [ "$j" -lt "$filled" ]; then bar="${bar}█"; else bar="${bar}░"; fi
		j=$((j + 1))
	done
	printf '\r  %s %s %s%s%s %3d%%  %s%s / %s%s\033[K' \
		"$glyph" "$label" "$C1" "$bar" "$RESET" "$pct" \
		"$DIM" "$(hsize "$cur")" "$tdisp" "$RESET"
}

watch_bytes() {
	local pid=$1 label=$2 total=$3
	shift 3
	local i=0 rc=0 cur=0
	printf '\033[?25l'
	while kill -0 "$pid" 2>/dev/null; do
		cur=$("$@" 2>/dev/null || echo 0)
		draw_bar "${CYAN}${SPIN[$((i % 10))]}${RESET}" "$label" "$cur" "$total"
		i=$((i + 1))
		sleep 0.2
	done
	wait "$pid" || rc=$?
	printf '\033[?25h'
	if [ "$rc" -eq 0 ]; then
		if [ "$total" -le 0 ]; then
			total=$("$@" 2>/dev/null || echo 0)
		fi
		draw_bar "${GREEN}✔${RESET}" "$label" "$total" "$total"
		printf '\n'
	else
		printf '\r  %s✘%s %s failed\033[K\n' "$RED" "$RESET" "$label"
	fi
	return "$rc"
}

run_task() {
	local label=$1
	shift
	if [ "$FANCY" = no ]; then
		echo "==> $label"
		"$@"
		return
	fi
	local i=0 rc=0 pid log
	log="$(mktemp "${TMPDIR:-/tmp}/macmirror-task.XXXXXX")"
	"$@" >"$log" 2>&1 &
	pid=$!
	printf '\033[?25l'
	while kill -0 "$pid" 2>/dev/null; do
		printf '\r  %s%s%s %s\033[K' "$CYAN" "${SPIN[$((i % 10))]}" "$RESET" "$label"
		i=$((i + 1))
		sleep 0.1
	done
	wait "$pid" || rc=$?
	printf '\033[?25h'
	if [ "$rc" -eq 0 ]; then
		printf '\r  %s✔%s %s\033[K\n' "$GREEN" "$RESET" "$label"
	else
		printf '\r  %s✘%s %s failed\033[K\n' "$RED" "$RESET" "$label"
		tail -n 20 "$log" >&2 || true
	fi
	rm -f "$log"
	return "$rc"
}

draw_pct_bar() {
	local glyph=$1 label=$2 cur=$3 total=$4
	local pct=0 filled=0 bar='' j=0
	if [ "$total" -gt 0 ]; then
		pct=$((cur * 100 / total))
		[ "$pct" -gt 100 ] && pct=100
	fi
	filled=$((pct * BAR_WIDTH / 100))
	while [ "$j" -lt "$BAR_WIDTH" ]; do
		if [ "$j" -lt "$filled" ]; then bar="${bar}█"; else bar="${bar}░"; fi
		j=$((j + 1))
	done
	printf '\r  %s %s %s%s%s %3d%%\033[K' \
		"$glyph" "$label" "$C1" "$bar" "$RESET" "$pct"
}

watch_build_progress() {
	local label=$1 pfile=$2
	shift 2
	if [ "$FANCY" = no ]; then
		echo "==> $label"
		"$@"
		return
	fi
	local i=0 rc=0 pid log cur=0 total=0 phase=""
	log="$(mktemp "${TMPDIR:-/tmp}/macmirror-build.XXXXXX")"
	: > "$pfile"
	"$@" >"$log" 2>&1 &
	pid=$!
	printf '\033[?25l'
	while kill -0 "$pid" 2>/dev/null; do
		if read -r cur total phase < "$pfile" 2>/dev/null && [ -n "${total:-}" ] && [ "$total" -gt 0 ] 2>/dev/null; then
			draw_pct_bar "${CYAN}${SPIN[$((i % 10))]}${RESET}" "$label" "$cur" "$total"
		else
			printf '\r  %s%s%s %s\033[K' "$CYAN" "${SPIN[$((i % 10))]}" "$RESET" "$label"
		fi
		i=$((i + 1))
		sleep 0.15
	done
	wait "$pid" || rc=$?
	printf '\033[?25h'
	if [ "$rc" -eq 0 ]; then
		draw_pct_bar "${GREEN}✔${RESET}" "$label" 100 100
		printf '\n'
	else
		printf '\r  %s✘%s %s failed\033[K\n' "$RED" "$RESET" "$label"
		tail -n 20 "$log" >&2 || true
	fi
	rm -f "$log" "$pfile"
	return "$rc"
}

usage() {
	cat <<EOF
Usage: $(basename "$0") [options] [game_files_or_installer]

Options:
  -g, --game <path>   Path to Mirror's Edge folder, .app, or GOG setup_mirrors_edge*.exe
      --lang <code>   GOG installer language filter (default: en-US, or 'all')
      --dmg           Also wrap Mirror's Edge.app into ~/Downloads/Mirror's Edge.dmg
      --local <dir>   Use a local macMirror checkout instead of downloading from GitHub
      --dest <dir>    Install directory (default: ~/Downloads)
  -h, --help          Show this help message

When run again on a Mac with an existing Mirror's Edge.app (/Applications, ~/Applications,
or ~/Downloads), the app bundle is rebuilt and updated in-place while preserving saves,
configs, and your Metal shader cache in ~/Library/Application Support/Mirror's Edge Native.

Environment overrides:
  MACMIRROR_REPO      GitHub owner/repo (default: $REPO)
  MACMIRROR_BRANCH    GitHub branch/tag (default: $BRANCH)
  MACMIRROR_GH_TOKEN  GitHub token if pulling from a private repository
EOF
}

# ---------------------------------------------------------------------------
# Case-insensitive lookup & Mirror's Edge installation validation.
# ---------------------------------------------------------------------------
find_ci_dir() {
	local parent=$1 target_lower=$2 entry base lower
	[ -d "$parent" ] || return 1
	for entry in "$parent"/*; do
		[ -d "$entry" ] || continue
		base="$(basename "$entry")"
		lower="$(printf '%s' "$base" | tr '[:upper:]' '[:lower:]')"
		if [ "$lower" = "$target_lower" ]; then
			printf '%s\n' "$entry"
			return 0
		fi
	done
	return 1
}

find_ci_file() {
	local parent=$1 target_lower=$2 entry base lower
	[ -d "$parent" ] || return 1
	for entry in "$parent"/*; do
		[ -f "$entry" ] || continue
		base="$(basename "$entry")"
		lower="$(printf '%s' "$base" | tr '[:upper:]' '[:lower:]')"
		if [ "$lower" = "$target_lower" ]; then
			printf '%s\n' "$entry"
			return 0
		fi
	done
	return 1
}

validate_game_dir() {
	local root=$1 bin eng td
	bin="$(find_ci_dir "$root" "binaries")" || return 1
	eng="$(find_ci_dir "$root" "engine")" || return 1
	td="$(find_ci_dir "$root" "tdgame")" || return 1
	find_ci_file "$bin" "mirrorsedge.exe" >/dev/null || return 1
	find_ci_file "$bin" "physxcore.dll" >/dev/null || find_ci_file "$bin" "physxcore.bak" >/dev/null || return 1
	find_ci_file "$bin" "binkw32.dll" >/dev/null || return 1
	find_ci_dir "$td" "cookedpc" >/dev/null || return 1
	return 0
}

resolve_game_dir() {
	local base="${1%/}" root dir cand
	for root in "$base" "$base.app"; do
		[ -d "$root" ] || continue
		if [ "$(basename "$root" | tr '[:upper:]' '[:lower:]')" = "binaries" ]; then
			cand="$(dirname "$root")"
			if validate_game_dir "$cand"; then
				printf '%s\n' "$cand"
				return 0
			fi
		fi
		for dir in \
			"$root" \
			"$root/Contents/Resources/GameData" \
			"$root/work/game_data" \
			"$root/Mirror's Edge" \
			"$root/Mirrors Edge" \
			"$root/app" \
			"$root/app/Mirror's Edge" \
			"$root/drive_c/GOG Games/Mirror's Edge" \
			"$root/drive_c/GOG Games/Mirrors Edge" \
			"$root/drive_c/Program Files/EA Games/Mirror's Edge" \
			"$root/drive_c/Program Files (x86)/EA Games/Mirror's Edge" \
			"$root/drive_c/Program Files/Mirror's Edge" \
			"$root/drive_c/Program Files (x86)/Mirror's Edge" \
			"$root/drive_c/Program Files/Steam/steamapps/common/Mirror's Edge" \
			"$root/drive_c/Program Files (x86)/Steam/steamapps/common/Mirror's Edge" \
			"$root/drive_c/Program Files (x86)/Steam/steamapps/common/mirrors edge" \
			"$root/Contents/Resources/drive_c/GOG Games/Mirror's Edge" \
			"$root/Contents/SharedSupport/prefix/drive_c/GOG Games/Mirror's Edge" \
			"$root/Contents/SharedSupport/prefix/drive_c/Program Files (x86)/EA Games/Mirror's Edge"
		do
			if validate_game_dir "$dir"; then
				printf '%s\n' "$dir"
				return 0
			fi
		done
	done
	return 1
}

collect_install_candidates() {
	CAND_DIRS=(
		"$PWD/work/game_data"
		"$HOME/Library/Application Support/Steam/steamapps/common/Mirror's Edge"
		"$HOME/Library/Application Support/Steam/steamapps/common/mirrors edge"
		"$HOME/Games/Heroic/Mirror's Edge"
		"$HOME/Games/Heroic/Mirrors Edge"
		"$HOME/Games/Mirror's Edge"
		"$HOME/Games/Mirrors Edge"
		"$DL/Mirror's Edge"
		"$DL/Mirrors Edge"
		"$HOME/Desktop/Mirror's Edge"
		"$HOME/Desktop/Mirrors Edge"
	)
	local vdf="$HOME/Library/Application Support/Steam/steamapps/libraryfolders.vdf"
	if [ -f "$vdf" ]; then
		local lib depot
		while IFS= read -r lib; do
			[ -d "$lib" ] || continue
			CAND_DIRS+=(
				"$lib/steamapps/common/Mirror's Edge"
				"$lib/steamapps/common/mirrors edge"
			)
			for depot in "$lib/steamapps/content"/app_17410/depot_*; do
				if [ -d "$depot" ]; then
					CAND_DIRS+=("$depot")
				fi
			done
		done <<EOF
$(sed -n 's/^[[:space:]]*"path"[[:space:]]*"\([^"]*\)".*/\1/p' "$vdf")
EOF
	fi
	local depot
	for depot in \
		"$HOME/Library/Application Support/Steam/Steam.AppBundle/Steam/Contents/MacOS/steamapps/content"/app_17410/depot_* \
		"$HOME/Library/Application Support/Steam/steamapps/content"/app_17410/depot_*
	do
		if [ -d "$depot" ]; then
			CAND_DIRS+=("$depot")
		fi
	done
	local bottle
	for bottle in \
		"$HOME/Library/Application Support/CrossOver/Bottles"/* \
		"$HOME/Library/Containers/com.isaacmarovitz.Whisky/Bottles"/* \
		"$HOME/Applications/Porting Kit"/*
	do
		if [ -d "$bottle" ]; then
			CAND_DIRS+=("$bottle")
		fi
	done
	return 0
}

# Parse arguments.
WANT_DMG=no
LOCAL_SRC=""
GAME_ARG=""
GOG_LANG="en-US"
DEST_DIR="${MACMIRROR_DEST_DIR:-$DL}"
while [ $# -gt 0 ]; do
	case "$1" in
		--dmg) WANT_DMG=yes; shift ;;
		-g|--game)
			[ $# -ge 2 ] || die "$1 requires a path to your Mirror's Edge folder or GOG installer .exe"
			GAME_ARG="$2"; shift 2 ;;
		--game=*)
			GAME_ARG="${1#--game=}"; shift ;;
		--lang)
			[ $# -ge 2 ] || die "--lang requires a language code (e.g. en-US) or 'all'"
			GOG_LANG="$2"; shift 2 ;;
		--lang=*)
			GOG_LANG="${1#--lang=}"; shift ;;
		--local)
			[ $# -ge 2 ] || die "--local requires a path to a macMirror repo checkout"
			LOCAL_SRC="$2"; shift 2 ;;
		--dest)
			[ $# -ge 2 ] || die "--dest requires a directory path"
			DEST_DIR="$2"; shift 2 ;;
		-h|--help) usage; exit 0 ;;
		-*) die "unknown option: $1" ;;
		*) GAME_ARG="$1"; shift ;;
	esac
done

banner

if [ "$(uname -sm)" != "Darwin arm64" ]; then
	die "this installer is for Apple Silicon Macs (arm64) only"
fi

TMP="$(mktemp -d)"
DEV=""
cleanup() {
	kill $(jobs -p) 2>/dev/null || true
	[ -n "$DEV" ] && hdiutil detach "$DEV" >/dev/null 2>&1 || true
	[ -n "$TMP" ] && rm -rf "$TMP"
	[ "$FANCY" = yes ] && printf '\033[?25h' || true
}
trap cleanup EXIT

