__INNOEXTRACT_GZ_B64__
	local actual
	actual="$(shasum -a 256 "$out" | awk '{print $1}')"
	[ "$actual" = "$INNO_SHA256" ] || die "embedded innoextract integrity check failed ($actual != $INNO_SHA256)"
	chmod +x "$out"
	xattr -cr "$out" 2>/dev/null || true
	codesign --force --sign - "$out" >/dev/null 2>&1 || true
}

ensure_innoextract() {
	if [ -n "$INNO_BIN" ] && [ -x "$INNO_BIN" ]; then
		return 0
	fi
	if [ -x "$TOOLS_DIR/innoextract" ]; then
		local cached_sha
		cached_sha="$(shasum -a 256 "$TOOLS_DIR/innoextract" 2>/dev/null | awk '{print $1}')"
		if [ "$cached_sha" = "$INNO_SHA256" ]; then
			INNO_BIN="$TOOLS_DIR/innoextract"
			return 0
		fi
	fi
	run_task "Preparing built-in standalone innoextract" extract_embedded_innoextract "$TOOLS_DIR/innoextract"
	INNO_BIN="$TOOLS_DIR/innoextract"
}

