__LLVM_X86_GZ_B64__
	local actual
	actual="$(shasum -a 256 "$out" | awk '{print $1}')"
	[ "$actual" = "$LLVM_X86_SHA256" ] || die "embedded libLLVM integrity check failed ($actual != $LLVM_X86_SHA256)"
	chmod 755 "$out"
	xattr -cr "$out" 2>/dev/null || true
	codesign --force --sign - "$out" >/dev/null 2>&1 || true
}

ensure_llvm_disasm() {
	local cand
	for cand in "/opt/homebrew/opt/llvm/lib" "/usr/local/opt/llvm/lib"; do
		if [ -e "$cand/libLLVM.dylib" ]; then
			LLVM_LIB_DIR="$cand"
			return 0
		fi
	done
	local dst="$TOOLS_DIR/llvm/libLLVM.dylib"
	if [ -f "$dst" ] && [ "$(shasum -a 256 "$dst" 2>/dev/null | awk '{print $1}')" = "$LLVM_X86_SHA256" ]; then
		LLVM_LIB_DIR="$TOOLS_DIR/llvm"
		return 0
	fi
	run_task "Preparing built-in X86 disassembler (libLLVM)" extract_embedded_llvm "$dst"
	LLVM_LIB_DIR="$TOOLS_DIR/llvm"
}


GOG_EXTRACT_DIR=""
extract_gog_installer() {
	local exe=$1
	ensure_innoextract
	GOG_EXTRACT_DIR="$TMP/gog_inno"
	rm -rf "$GOG_EXTRACT_DIR"
	mkdir -p "$GOG_EXTRACT_DIR"

	normalize_gog_extracted() {
		local root=$1 dir bin bak local_dir pload
		for dir in "$root" "$root/app" "$root/Mirror's Edge" "$root/Mirrors Edge" "$root/app/Mirror's Edge"; do
			[ -d "$dir" ] || continue
			bin="$(find_ci_dir "$dir" "binaries" || true)"
			[ -n "$bin" ] || continue
			if ! find_ci_file "$bin" "physxcore.dll" >/dev/null 2>&1; then
				bak="$(find_ci_file "$bin" "physxcore.bak" || true)"
				if [ -n "$bak" ]; then
					cp -c "$bak" "$bin/PhysXCore.dll" 2>/dev/null || cp "$bak" "$bin/PhysXCore.dll" || true
				fi
			fi
			if ! find_ci_file "$bin" "physxloader.dll" >/dev/null 2>&1; then
				local_dir="$(find_ci_dir "$bin" "physxlocal" || true)"
				if [ -n "$local_dir" ]; then
					pload="$(find_ci_file "$local_dir" "physxloader.dll" || true)"
					if [ -n "$pload" ]; then
						cp -c "$pload" "$bin/PhysXLoader.dll" 2>/dev/null || cp "$pload" "$bin/PhysXLoader.dll" || true
					fi
				fi
			fi
		done
	}

	gog_list_bytes() {
		local lang=$1
		local -a cmd=("$INNO_BIN" -l)
		[ "$lang" = "all" ] || cmd+=(--language="$lang")
		cmd+=("$exe")
		"${cmd[@]}" 2>/dev/null | python3 -c '
import re, sys
u = {"B": 1, "KiB": 1024, "MiB": 1024**2, "GiB": 1024**3}
tot = 0
for line in sys.stdin:
    m = re.search(r"\(([0-9]+(?:\.[0-9]+)?)\s+(B|KiB|MiB|GiB)\)", line)
    if m:
        tot += int(float(m.group(1)) * u[m.group(2)])
print(tot)
' 2>/dev/null || echo 0
	}

	run_gog_with_bar() {
		local lang=$1 label=$2 total_b=0 rc=0 log
		local -a cmd=("$INNO_BIN" -e -s)
		[ "$lang" = "all" ] || cmd+=(--language="$lang")
		cmd+=(-d "$GOG_EXTRACT_DIR" "$exe")
		if [ "$FANCY" = no ]; then
			echo "==> $label"
			"${cmd[@]}" || return 1
			return 0
		fi
		total_b="$(gog_list_bytes "$lang")"
		log="$(mktemp "${TMPDIR:-/tmp}/macmirror-inno.XXXXXX")"
		"${cmd[@]}" >"$log" 2>&1 &
		if ! watch_bytes $! "$label" "${total_b:-0}" du_bytes "$GOG_EXTRACT_DIR"; then
			rc=1
			tail -n 20 "$log" >&2 || true
		fi
		rm -f "$log"
		return "$rc"
	}

	if [ "$GOG_LANG" != "all" ]; then
		run_gog_with_bar "$GOG_LANG" "Extracting game files" \
			|| die "failed to extract GOG installer: $(basename "$exe")"
		normalize_gog_extracted "$GOG_EXTRACT_DIR"
		ASSET_SRC="$(resolve_game_dir "$GOG_EXTRACT_DIR" || true)"
		if [ -z "$ASSET_SRC" ]; then
			rm -rf "$GOG_EXTRACT_DIR" && mkdir -p "$GOG_EXTRACT_DIR"
			run_gog_with_bar "all" "Extracting game files" \
				|| die "failed to extract GOG installer: $(basename "$exe")"
			normalize_gog_extracted "$GOG_EXTRACT_DIR"
		fi
	else
		run_gog_with_bar "all" "Extracting game files" \
			|| die "failed to extract GOG installer: $(basename "$exe")"
		normalize_gog_extracted "$GOG_EXTRACT_DIR"
	fi
	ASSET_SRC="$(resolve_game_dir "$GOG_EXTRACT_DIR" || true)"
	[ -n "$ASSET_SRC" ] || die "complete Mirror's Edge files not found inside: $(basename "$exe")" \
		"Make sure all setup_mirrors_edge_*.bin parts are in the same folder as $(basename "$exe")."
	ok "Extracted game files from $(basename "$exe")"
}

# Detect if invoked from inside a local macMirror repo checkout.
SCRIPT_DIR=""
if [ -n "${BASH_SOURCE[0]:-}" ] && [ -f "${BASH_SOURCE[0]}" ]; then
	SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
fi
if [ -z "$LOCAL_SRC" ] && [ -n "$SCRIPT_DIR" ] && [ -f "$SCRIPT_DIR/CMakeLists.txt" ] && [ -f "$SCRIPT_DIR/tools/setup_lifted.py" ]; then
	LOCAL_SRC="$SCRIPT_DIR"
fi

# ---------------------------------------------------------------------------
# Step 1: Locate Mirror's Edge game files (folder, existing .app, or GOG .exe).
# ---------------------------------------------------------------------------
step "Locating your Mirror's Edge game files"

EXISTING_APP=""
EXISTING_ICNS=""
EXISTING_DEPS=""
EXISTING_VER=""
ASSET_SRC=""
collect_install_candidates

APP_SEARCH_LIST=(
	"/Applications/$APP_NAME.app"
	"$HOME/Applications/$APP_NAME.app"
	"$DL/$APP_NAME.app"
)
if [ -n "${MACMIRROR_DEST_DIR:-}" ]; then
	APP_SEARCH_LIST=("${MACMIRROR_DEST_DIR%/}/$APP_NAME.app" "${APP_SEARCH_LIST[@]}")
fi
for app in "${APP_SEARCH_LIST[@]}"; do
	if validate_game_dir "$app/Contents/Resources/GameData"; then
		EXISTING_APP="$app"
		[ -f "$app/Contents/Resources/MirrorsEdge.icns" ] && EXISTING_ICNS="$app/Contents/Resources/MirrorsEdge.icns"
		[ -d "$app/Contents/Resources/pc-deps" ] && EXISTING_DEPS="$app/Contents/Resources/pc-deps"
		EXISTING_VER="$(/usr/libexec/PlistBuddy -c "Print :CFBundleShortVersionString" "$app/Contents/Info.plist" 2>/dev/null || true)"
		if [ -z "$GAME_ARG" ]; then
			ASSET_SRC="$app/Contents/Resources/GameData"
			ok "Found existing installation: $app${EXISTING_VER:+ (v$EXISTING_VER)}"
		fi
		break
	fi
done

if [ -n "$GAME_ARG" ]; then
	if [ -f "$GAME_ARG" ]; then
		case "$(printf '%s' "$GAME_ARG" | tr '[:upper:]' '[:lower:]')" in
			*.exe) extract_gog_installer "$GAME_ARG" ;;
			*) die "expected a Mirror's Edge folder, .app, or GOG setup .exe installer: $GAME_ARG" ;;
		esac
	elif ! ASSET_SRC="$(resolve_game_dir "$GAME_ARG")"; then
		die "complete Mirror's Edge files not found in: $GAME_ARG" \
			"Pass the Mirror's Edge folder (Binaries, Engine, TdGame) or GOG setup_mirrors_edge_*.exe."
	else
		ok "Using game files from $ASSET_SRC"
	fi
elif [ -z "$ASSET_SRC" ]; then
	for cand in "${CAND_DIRS[@]}"; do
		if ASSET_SRC="$(resolve_game_dir "$cand")"; then
			ok "Using game files from $ASSET_SRC"
			break
		fi
		ASSET_SRC=""
	done

	if [ -z "$ASSET_SRC" ]; then
		for search_root in "$PWD" "$DL" "$HOME/Desktop" "$HOME/Games"; do
			[ -d "$search_root" ] || continue
			for cand in "$search_root"/*; do
				[ -d "$cand" ] || continue
				case "$(basename "$cand" | tr '[:upper:]' '[:lower:]')" in
					*mirror*) ;;
					*) continue ;;
				esac
				if ASSET_SRC="$(resolve_game_dir "$cand")"; then
					ok "Using game files from $ASSET_SRC"
					break 2
				fi
				ASSET_SRC=""
			done
		done
	fi

	if [ -z "$ASSET_SRC" ]; then
		GOG_EXE=""
		for search_root in "$PWD" "$DL" "$HOME/Desktop" "$HOME/Games"; do
			[ -d "$search_root" ] || continue
			for cand in "$search_root"/*.exe "$search_root"/*.EXE; do
				[ -f "$cand" ] || continue
				case "$(basename "$cand" | tr '[:upper:]' '[:lower:]')" in
					setup_mirrors_edge*.exe|setup_mirror*edge*.exe|mirrors_edge*.exe)
						GOG_EXE="$cand"
						break 2 ;;
				esac
			done
		done
		if [ -n "$GOG_EXE" ]; then
			extract_gog_installer "$GOG_EXE"
		fi
	fi

	if [ -z "$ASSET_SRC" ]; then
		die "Mirror's Edge game files not found" \
			"Place your GOG offline installer (setup_mirrors_edge_*.exe + .bin parts) or Mirror's Edge folder in ~/Downloads," \
			"or pass its path explicitly with --game:" \
			"  curl -fsSL https://raw.githubusercontent.com/$REPO/$BRANCH/quick-install.sh | bash -s -- --game ~/path/to/\"Mirror's Edge\""
	fi
fi

# ---------------------------------------------------------------------------
# Step 2: Fetch macMirror source and verify build toolchain.
# ---------------------------------------------------------------------------
step "Preparing macMirror source & native ARM64 build tools"

SRC_WORK="$TMP/macMirror-src"
if [ -n "$LOCAL_SRC" ]; then
	[ -f "$LOCAL_SRC/CMakeLists.txt" ] || die "CMakeLists.txt missing in $LOCAL_SRC"
	# If local checkout already has matching build or writable tree, reuse cleanly or copy clean source.
	if [ -d "$LOCAL_SRC/build/RunnerMetal.app/Contents/MacOS" ] && [ -d "$LOCAL_SRC/work/pc-deps" ]; then
		SRC_WORK="$LOCAL_SRC"
		ok "Using local macMirror checkout: $LOCAL_SRC"
	else
		mkdir -p "$SRC_WORK"
		cp "$LOCAL_SRC/CMakeLists.txt" "$LOCAL_SRC/LICENSE.md" "$LOCAL_SRC/README.md" "$SRC_WORK/" 2>/dev/null || cp "$LOCAL_SRC/CMakeLists.txt" "$SRC_WORK/"
		for d in assets cmake src third_party tools; do
			[ -d "$LOCAL_SRC/$d" ] || continue
			mkdir -p "$SRC_WORK/$d"
			if [ "$d" = "src" ]; then
				[ -d "$LOCAL_SRC/src/d3d9_metal" ] && cp -R "$LOCAL_SRC/src/d3d9_metal" "$SRC_WORK/src/"
				[ -d "$LOCAL_SRC/src/host_macos" ] && cp -R "$LOCAL_SRC/src/host_macos" "$SRC_WORK/src/"
				if [ -f "$LOCAL_SRC/src/lifted/lifted_sources.cmake" ]; then
					cp -c -R "$LOCAL_SRC/src/lifted" "$SRC_WORK/src/lifted" 2>/dev/null || cp -R "$LOCAL_SRC/src/lifted" "$SRC_WORK/src/lifted"
				fi
			else
				cp -R "$LOCAL_SRC/$d"/. "$SRC_WORK/$d/"
			fi
		done
		if [ -d "$LOCAL_SRC/work/pc-deps/rebased" ] && [ -f "$LOCAL_SRC/work/pc-deps/msvcr80.dll" ] && [ -f "$LOCAL_SRC/work/pc-deps/msvcp80.dll" ]; then
			mkdir -p "$SRC_WORK/work"
			cp -c -R "$LOCAL_SRC/work/pc-deps" "$SRC_WORK/work/pc-deps" 2>/dev/null || cp -R "$LOCAL_SRC/work/pc-deps" "$SRC_WORK/work/pc-deps"
		fi
		ok "Copied clean source from $LOCAL_SRC"
	fi
else
	GH_TOKEN_VAL="${MACMIRROR_GH_TOKEN:-${GITHUB_TOKEN:-${GH_TOKEN:-}}}"
	if [ -z "$GH_TOKEN_VAL" ] && command -v gh >/dev/null 2>&1; then
		GH_TOKEN_VAL="$(gh auth token 2>/dev/null || true)"
	fi
	TAR_URL="https://api.github.com/repos/$REPO/tarball/$BRANCH"
	TAR_PATH="$TMP/macMirror.tar.gz"
	fetch_src() {
		if [ -n "$GH_TOKEN_VAL" ]; then
			curl -fsSL -H "Authorization: Bearer $GH_TOKEN_VAL" -H "Accept: application/vnd.github+json" -o "$TAR_PATH" "$TAR_URL"
		else
			curl -fsSL -o "$TAR_PATH" "https://github.com/$REPO/archive/refs/heads/$BRANCH.tar.gz"
		fi
	}
	run_task "Downloading macMirror ($REPO@$BRANCH)" fetch_src \
		|| die "failed to download macMirror source from $REPO ($BRANCH)" \
			"If this repository is private, run 'gh auth login' or set MACMIRROR_GH_TOKEN."
	mkdir -p "$SRC_WORK"
	run_task "Unpacking macMirror source" tar -xzf "$TAR_PATH" --strip-components=1 -C "$SRC_WORK"
fi

xcrun -f clang >/dev/null 2>&1 && xcrun -f clang++ >/dev/null 2>&1 && xcrun -f codesign_allocate >/dev/null 2>&1 \
	|| die "Xcode Command Line Tools are required" \
		"Run 'xcode-select --install' in Terminal, then re-run this script."
command -v python3 >/dev/null 2>&1 \
	|| die "python3 is required (included with Xcode Command Line Tools)" \
		"Run 'xcode-select --install' in Terminal, then re-run this script."

LLVM_LIB_DIR=""
ensure_llvm_disasm

SDL3_MODE=""
SDL3_INC=""
SDL3_DYLIB=""
SDL3_DMG_URL="https://github.com/libsdl-org/SDL/releases/download/release-3.4.20/SDL3-3.4.20.dmg"
SDL3_DMG_SHA256="36b7e4cefcf7d55d227b3df5e686f8f33ab34193173a976445d1b57c80009e44"

ensure_sdl3() {
	local pfx
	for pfx in "/opt/homebrew" "/usr/local"; do
		if [ -d "$pfx/opt/sdl3/include" ] && [ -e "$pfx/opt/sdl3/lib/libSDL3.0.dylib" ]; then
			SDL3_MODE="dylib"
			SDL3_INC="$pfx/opt/sdl3/include"
			SDL3_DYLIB="$pfx/opt/sdl3/lib/libSDL3.0.dylib"
			return 0
		fi
	done
	if [ -x "$TOOLS_DIR/SDL3.framework/Versions/A/SDL3" ]; then
		SDL3_MODE="framework"
		return 0
	fi
	fetch_sdl3_framework() {
		local dmg="$TMP/SDL3.dmg" mnt=""
		curl -fsSL -o "$dmg" "$SDL3_DMG_URL"
		local actual
		actual="$(shasum -a 256 "$dmg" | awk '{print $1}')"
		[ "$actual" = "$SDL3_DMG_SHA256" ] || return 1
		mnt="$(hdiutil attach -nobrowse -readonly "$dmg" | awk '/\/Volumes\//{print $NF; exit}')"
		[ -n "$mnt" ] && [ -d "$mnt/SDL3.xcframework/macos-arm64_x86_64/SDL3.framework" ] || {
			[ -n "$mnt" ] && hdiutil detach "$mnt" >/dev/null 2>&1 || true
			return 1
		}
		mkdir -p "$TOOLS_DIR"
		rm -rf "$TOOLS_DIR/SDL3.framework"
		ditto "$mnt/SDL3.xcframework/macos-arm64_x86_64/SDL3.framework" "$TOOLS_DIR/SDL3.framework"
		hdiutil detach "$mnt" >/dev/null 2>&1 || true
		rm -f "$dmg"
	}
	run_task "Fetching official SDL3 framework (3.4.20)" fetch_sdl3_framework \
		|| die "failed to download or extract official SDL3.framework"
	SDL3_MODE="framework"
}
ensure_sdl3
ok "Build toolchain ready (Xcode Command Line Tools, zero Homebrew required)"

# ---------------------------------------------------------------------------
# Step 3: Lift x86 game binaries & compile native Metal RunnerMetal.app.
# ---------------------------------------------------------------------------
step "Lifting & compiling native Metal binary (RunnerMetal)"

cd "$SRC_WORK"
mkdir -p work/game_data work/pc-deps
if [ ! -d "$SRC_WORK/work/game_data/Binaries" ]; then
	for sub in "$ASSET_SRC"/*; do
		[ -e "$sub" ] || continue
		ln -sfn "$sub" "$SRC_WORK/work/game_data/$(basename "$sub")"
	done
	if ! find_ci_file "$SRC_WORK/work/game_data/Binaries" "physxcore.dll" >/dev/null 2>&1 || \
	   ! find_ci_file "$SRC_WORK/work/game_data/Binaries" "physxloader.dll" >/dev/null 2>&1; then
		src_bin_tmp="$(find_ci_dir "$ASSET_SRC" "binaries" || true)"
		bak_tmp="$(find_ci_file "$src_bin_tmp" "physxcore.bak" || true)"
		plocal_tmp="$(find_ci_dir "$src_bin_tmp" "physxlocal" || true)"
		pload_tmp=""
		[ -n "$plocal_tmp" ] && pload_tmp="$(find_ci_file "$plocal_tmp" "physxloader.dll" || true)"
		if [ -n "$src_bin_tmp" ] && { [ -n "$bak_tmp" ] || [ -n "$pload_tmp" ]; }; then
			rm -f "$SRC_WORK/work/game_data/Binaries"
			mkdir -p "$SRC_WORK/work/game_data/Binaries"
			for bf in "$src_bin_tmp"/*; do
				[ -e "$bf" ] || continue
				ln -sfn "$bf" "$SRC_WORK/work/game_data/Binaries/$(basename "$bf")"
			done
			if ! find_ci_file "$SRC_WORK/work/game_data/Binaries" "physxcore.dll" >/dev/null 2>&1 && [ -n "$bak_tmp" ]; then
				ln -sfn "$bak_tmp" "$SRC_WORK/work/game_data/Binaries/PhysXCore.dll"
			fi
			if ! find_ci_file "$SRC_WORK/work/game_data/Binaries" "physxloader.dll" >/dev/null 2>&1 && [ -n "$pload_tmp" ]; then
				ln -sfn "$pload_tmp" "$SRC_WORK/work/game_data/Binaries/PhysXLoader.dll"
			fi
		fi
	fi
fi
if [ -n "$EXISTING_DEPS" ] && [ -f "$EXISTING_DEPS/msvcr80.dll" ] && [ -f "$EXISTING_DEPS/msvcp80.dll" ]; then
	[ -f "$SRC_WORK/work/pc-deps/msvcr80.dll" ] || cp -L "$EXISTING_DEPS/msvcr80.dll" "$SRC_WORK/work/pc-deps/msvcr80.dll"
	[ -f "$SRC_WORK/work/pc-deps/msvcp80.dll" ] || cp -L "$EXISTING_DEPS/msvcp80.dll" "$SRC_WORK/work/pc-deps/msvcp80.dll"
fi

compute_lifted_cache_key() {
	python3 - "$SRC_WORK" "$ASSET_SRC" "$EXISTING_DEPS" <<'PY'
import hashlib, os, sys
src_work, asset_src, existing_deps = sys.argv[1], sys.argv[2], sys.argv[3]
h = hashlib.sha256()

def hash_file(tag, path):
    h.update(tag.encode("utf-8") + b"\0")
    with open(path, "rb") as fp:
        while True:
            chunk = fp.read(1 << 20)
            if not chunk:
                break
            h.update(chunk)
    h.update(b"\0")

def find_ci(root, name_lower):
    if not root or not os.path.isdir(root):
        return None
    for fn in os.listdir(root):
        if fn.lower() == name_lower:
            p = os.path.join(root, fn)
            if os.path.isfile(p):
                return p
    return None

bin_dir = None
for fn in os.listdir(asset_src):
    if fn.lower() == "binaries" and os.path.isdir(os.path.join(asset_src, fn)):
        bin_dir = os.path.join(asset_src, fn)
        break
for name in (
    "mirrorsedge.exe", "physxloader.dll", "physxcore.dll", "nxcooking.dll",
    "physxextensions.dll", "nxcharacter.dll", "ogg.dll", "vorbis.dll",
    "vorbisfile.dll", "vorbisenc.dll", "libresample.dll", "binkw32.dll",
):
    p = find_ci(bin_dir, name)
    if not p and name == "physxcore.dll":
        p = find_ci(bin_dir, "physxcore.bak")
    if not p and name == "physxloader.dll" and bin_dir:
        for fn in os.listdir(bin_dir):
            if fn.lower() == "physxlocal" and os.path.isdir(os.path.join(bin_dir, fn)):
                p = find_ci(os.path.join(bin_dir, fn), "physxloader.dll")
                break
    if p:
        hash_file("pe:" + name, p)

r80 = find_ci(os.path.join(src_work, "work", "pc-deps"), "msvcr80.dll") or find_ci(existing_deps, "msvcr80.dll")
p80 = find_ci(os.path.join(src_work, "work", "pc-deps"), "msvcp80.dll") or find_ci(existing_deps, "msvcp80.dll")
if r80 and p80:
    hash_file("crt:msvcr80.dll", r80)
    hash_file("crt:msvcp80.dll", p80)
else:
    found_vc = False
    for root, dirs, files in os.walk(asset_src, followlinks=True):
        dirs.sort()
        for fn in sorted(files):
            if fn.lower() == "vcredist_x86.exe":
                hash_file("vcredist", os.path.join(root, fn))
                found_vc = True
                break
        if found_vc:
            break

tools_dir = os.path.join(src_work, "tools")
for fn in (
    "setup_lifted.py", "catalog.py", "lift.py", "gen_module.py",
    "xflags.py", "x86cfg.py", "eh.py", "pe32.py", "rebase_pe.py", "extract_vcredist.c",
):
    tp = os.path.join(tools_dir, fn)
    if os.path.isfile(tp):
        hash_file("tool:" + fn, tp)

print(h.hexdigest()[:20])
PY
}

LIFTED_CACHE_KEY="$(compute_lifted_cache_key 2>/dev/null || true)"
LIFTED_CACHE_ENTRY=""
[ -n "$LIFTED_CACHE_KEY" ] && LIFTED_CACHE_ENTRY="$CACHE_DIR/lifted/$LIFTED_CACHE_KEY"

if [ ! -f "$SRC_WORK/src/lifted/lifted_sources.cmake" ] && [ -n "$LIFTED_CACHE_ENTRY" ] \
	&& [ -f "$LIFTED_CACHE_ENTRY/lifted/lifted_sources.cmake" ] \
	&& [ -d "$LIFTED_CACHE_ENTRY/pc-deps/rebased" ] \
	&& [ -f "$LIFTED_CACHE_ENTRY/pc-deps/msvcr80.dll" ] \
	&& [ -f "$LIFTED_CACHE_ENTRY/pc-deps/msvcp80.dll" ]; then
	mkdir -p "$SRC_WORK/src" "$SRC_WORK/work"
	rm -rf "$SRC_WORK/src/lifted" "$SRC_WORK/work/pc-deps"
	(cp -c -R "$LIFTED_CACHE_ENTRY/lifted" "$SRC_WORK/src/lifted" 2>/dev/null || cp -R "$LIFTED_CACHE_ENTRY/lifted" "$SRC_WORK/src/lifted") \
		&& (cp -c -R "$LIFTED_CACHE_ENTRY/pc-deps" "$SRC_WORK/work/pc-deps" 2>/dev/null || cp -R "$LIFTED_CACHE_ENTRY/pc-deps" "$SRC_WORK/work/pc-deps") \
		&& ok "Restored cached lifted C modules (skipping x86 lifting)"
fi

if [ ! -f "$SRC_WORK/src/lifted/lifted_sources.cmake" ]; then
	run_task "Lifting x86 executable & PhysX/audio DLLs to ARM64 C" \
		env ME_PC_LLVM_LIB="$LLVM_LIB_DIR" python3 "$SRC_WORK/tools/setup_lifted.py" \
		|| die "static recompilation (setup_lifted.py) failed"
	SAVE_KEY="$(compute_lifted_cache_key 2>/dev/null || true)"
	[ -n "$SAVE_KEY" ] || SAVE_KEY="$LIFTED_CACHE_KEY"
	if [ -n "$SAVE_KEY" ] && [ -f "$SRC_WORK/src/lifted/lifted_sources.cmake" ] && [ -d "$SRC_WORK/work/pc-deps/rebased" ]; then
		SAVE_ENTRY="$CACHE_DIR/lifted/$SAVE_KEY"
		stage_cache="$SAVE_ENTRY.tmp.$$"
		rm -rf "$stage_cache"
		mkdir -p "$stage_cache" "$CACHE_DIR/lifted"
		if (cp -c -R "$SRC_WORK/src/lifted" "$stage_cache/lifted" 2>/dev/null || cp -R "$SRC_WORK/src/lifted" "$stage_cache/lifted") \
			&& (cp -c -R "$SRC_WORK/work/pc-deps" "$stage_cache/pc-deps" 2>/dev/null || cp -R "$SRC_WORK/work/pc-deps" "$stage_cache/pc-deps"); then
			for old_c in "$CACHE_DIR/lifted"/*; do
				[ -e "$old_c" ] || [ -L "$old_c" ] || continue
				[ "$old_c" = "$stage_cache" ] || rm -rf "$old_c" 2>/dev/null || true
			done
			mv "$stage_cache" "$SAVE_ENTRY" 2>/dev/null || rm -rf "$stage_cache"
			if [ -n "$LIFTED_CACHE_KEY" ] && [ "$LIFTED_CACHE_KEY" != "$SAVE_KEY" ] && [ -d "$SAVE_ENTRY" ]; then
				ln -sfn "$SAVE_KEY" "$CACHE_DIR/lifted/$LIFTED_CACHE_KEY" 2>/dev/null || true
			fi
		else
			rm -rf "$stage_cache"
		fi
	fi
elif [ "$SRC_WORK" = "$LOCAL_SRC" ] || [ -z "$LIFTED_CACHE_ENTRY" ] || [ ! -d "$LIFTED_CACHE_ENTRY" ]; then
	ok "Using pre-lifted C modules in src/lifted/"
fi

BUILD_PROGRESS_FILE="$TMP/build_progress"
build_direct_clang() {
	if [ "$SDL3_MODE" = "framework" ]; then
		python3 "$SRC_WORK/tools/build_macos.py" --out-dir "$SRC_WORK/build" --sdl-framework-dir "$TOOLS_DIR" --lifted-cache-dir "$CACHE_DIR/lifted-objs" --progress-file "$BUILD_PROGRESS_FILE"
	else
		python3 "$SRC_WORK/tools/build_macos.py" --out-dir "$SRC_WORK/build" --sdl-include "$SDL3_INC" --sdl-lib "$SDL3_DYLIB" --lifted-cache-dir "$CACHE_DIR/lifted-objs" --progress-file "$BUILD_PROGRESS_FILE"
	fi
}
watch_build_progress "Building RunnerMetal" "$BUILD_PROGRESS_FILE" build_direct_clang \
	|| die "Clang build of RunnerMetal failed"

BUILT_APP="$SRC_WORK/build/RunnerMetal.app"
[ -x "$BUILT_APP/Contents/MacOS/RunnerMetal" ] || die "RunnerMetal binary missing inside $BUILT_APP"

# ---------------------------------------------------------------------------
# Step 4: Package self-contained Mirror's Edge.app, extract icon & sign.
# ---------------------------------------------------------------------------
step "Packaging self-contained $APP_NAME.app"

APP="$TMP/$APP_NAME.app"
GDATA="$APP/Contents/Resources/GameData"
DEPS_OUT="$APP/Contents/Resources/pc-deps"
LIC_OUT="$APP/Contents/Resources/Licenses"
cp -c -R "$BUILT_APP" "$APP" 2>/dev/null || cp -R "$BUILT_APP" "$APP"

mkdir -p "$APP/Contents/Frameworks" "$GDATA" "$DEPS_OUT" "$LIC_OUT"
chmod +w "$APP/Contents/MacOS/RunnerMetal"
if [ "$SDL3_MODE" = "framework" ]; then
	ditto "$TOOLS_DIR/SDL3.framework" "$APP/Contents/Frameworks/SDL3.framework"
else
	cp -L "$SDL3_DYLIB" "$APP/Contents/Frameworks/libSDL3.0.dylib"
	chmod +w "$APP/Contents/Frameworks/libSDL3.0.dylib"
	codesign --remove-signature "$APP/Contents/Frameworks/libSDL3.0.dylib" 2>/dev/null || true
	install_name_tool -id "@rpath/libSDL3.0.dylib" "$APP/Contents/Frameworks/libSDL3.0.dylib" 2>/dev/null || true
	for ref in "$(otool -L "$APP/Contents/MacOS/RunnerMetal" | awk '/libSDL3/{print $1}')"; do
		[ -n "$ref" ] && install_name_tool -change "$ref" "@executable_path/../Frameworks/libSDL3.0.dylib" "$APP/Contents/MacOS/RunnerMetal" 2>/dev/null || true
	done
fi

[ -f "$SRC_WORK/LICENSE.md" ] && cp "$SRC_WORK/LICENSE.md" "$LIC_OUT/LICENSE.md"
[ -f "$SRC_WORK/src/host_macos/shatter/LICENSE" ] && cp "$SRC_WORK/src/host_macos/shatter/LICENSE" "$LIC_OUT/Shatter-LICENSE.txt"
[ -f "$SRC_WORK/third_party/dxbc-spirv/LICENSE" ] && cp "$SRC_WORK/third_party/dxbc-spirv/LICENSE" "$LIC_OUT/dxbc-spirv-LICENSE.txt"

copy_deref() {
	local src=$1 dst=$2
	if ! cp -c -R -L "$src" "$dst" 2>/dev/null; then
		rm -rf "$dst" 2>/dev/null || true
		cp -R -L "$src" "$dst"
	fi
}

SRC_BIN="$(find_ci_dir "$ASSET_SRC" "binaries")"
SRC_ENG="$(find_ci_dir "$ASSET_SRC" "engine")"
SRC_TD="$(find_ci_dir "$ASSET_SRC" "tdgame")"

bake_game_data() {
	copy_deref "$SRC_BIN" "$GDATA/Binaries"
	copy_deref "$SRC_ENG" "$GDATA/Engine"
	copy_deref "$SRC_TD" "$GDATA/TdGame"
	cp -L "$SRC_WORK/work/pc-deps/msvcr80.dll" "$DEPS_OUT/msvcr80.dll"
	cp -L "$SRC_WORK/work/pc-deps/msvcp80.dll" "$DEPS_OUT/msvcp80.dll"
	copy_deref "$SRC_WORK/work/pc-deps/rebased" "$DEPS_OUT/rebased"
	if ! find_ci_file "$GDATA/Binaries" "physxcore.dll" >/dev/null 2>&1; then
		bak="$(find_ci_file "$GDATA/Binaries" "physxcore.bak" || true)"
		if [ -n "$bak" ]; then
			cp -c "$bak" "$GDATA/Binaries/PhysXCore.dll" 2>/dev/null || cp "$bak" "$GDATA/Binaries/PhysXCore.dll" || true
		fi
	fi
	if ! find_ci_file "$GDATA/Binaries" "physxloader.dll" >/dev/null 2>&1; then
		plocal="$(find_ci_dir "$GDATA/Binaries" "physxlocal" || true)"
		if [ -n "$plocal" ]; then
			pload="$(find_ci_file "$plocal" "physxloader.dll" || true)"
			if [ -n "$pload" ]; then
				cp -c "$pload" "$GDATA/Binaries/PhysXLoader.dll" 2>/dev/null || cp "$pload" "$GDATA/Binaries/PhysXLoader.dll" || true
			fi
		fi
	fi
}

if [ "$FANCY" = yes ]; then
	BAKE_TOTAL=$(( $(du_bytes "$SRC_BIN") + $(du_bytes "$SRC_ENG") + $(du_bytes "$SRC_TD") ))
	bake_game_data &
	watch_bytes $! "Copying game assets" "$BAKE_TOTAL" du_bytes "$GDATA" \
		|| die "copying Mirror's Edge assets failed"
else
	echo "==> Copying Mirror's Edge assets into bundle..."
	bake_game_data
fi

extract_pe_icon() {
	local exe=$1 out_ico=$2
	command -v python3 >/dev/null 2>&1 || return 1
	python3 - "$exe" "$out_ico" <<'PY' >/dev/null 2>&1
import struct, sys
exe_path, out_path = sys.argv[1], sys.argv[2]
with open(exe_path, "rb") as f:
    pe = f.read()
pe_off = struct.unpack_from("<I", pe, 0x3C)[0]
num_sec = struct.unpack_from("<H", pe, pe_off + 6)[0]
opt_sz = struct.unpack_from("<H", pe, pe_off + 20)[0]
sec_off = pe_off + 24 + opt_sz
rsrc_raw = 0
sections = []
for i in range(num_sec):
    o = sec_off + i * 40
    name = pe[o:o+8].rstrip(b"\x00").decode("latin1", "ignore")
    vsz, va, rsz, raw = struct.unpack_from("<IIII", pe, o + 8)
    sections.append((va, vsz, raw, rsz))
    if name == ".rsrc":
        rsrc_raw = raw
assert rsrc_raw
def rva_off(rva):
    for va, vsz, raw, rsz in sections:
        if va <= rva < va + max(vsz, rsz):
            return raw + (rva - va)
    raise ValueError(rva)
def entries(off):
    _, _, _, _, nn, ni = struct.unpack_from("<IIHHHH", pe, off)
    return [struct.unpack_from("<II", pe, off + 16 + i * 8) for i in range(nn + ni)]
icons, groups = {}, []
for tid, tsub in entries(rsrc_raw):
    if tid in (3, 14) and (tsub & 0x80000000):
        for iid, isub in entries(rsrc_raw + (tsub & 0x7FFFFFFF)):
            if isub & 0x80000000:
                for _, lsub in entries(rsrc_raw + (isub & 0x7FFFFFFF)):
                    if not (lsub & 0x80000000):
                        rva, sz, _, _ = struct.unpack_from("<IIII", pe, rsrc_raw + lsub)
                        data = pe[rva_off(rva):rva_off(rva) + sz]
                        if tid == 3:
                            icons[iid] = data
                        else:
                            groups.append(data)
assert groups
grp = groups[0]
_, _, cnt = struct.unpack_from("<HHH", grp, 0)
blobs, dirs = [], []
offset = 6 + cnt * 16
for k in range(cnt):
    w, h, cc, res, pl, bpp, isz, icon_id = struct.unpack_from("<BBBBHHIH", grp, 6 + k * 14)
    blob = icons[icon_id]
    dirs.append(struct.pack("<BBBBHHII", w, h, cc, res, pl, bpp, len(blob), offset))
    blobs.append(blob)
    offset += len(blob)
with open(out_path, "wb") as f:
    f.write(struct.pack("<HHH", 0, 1, cnt))
    for d in dirs:
        f.write(d)
    for b in blobs:
        f.write(b)
PY
}

shape_macos_icon() {
	local png=$1
	command -v osascript >/dev/null 2>&1 || return 0
	osascript -l JavaScript - "$png" <<'JXA' >/dev/null 2>&1 || true
ObjC.import("Cocoa");
function run(argv) {
	var p = argv[0];
	var src = $.NSImage.alloc.initWithContentsOfFile(p);
	if (!src || !src.TIFFRepresentation) return;
	var size = 1024;
	var canvas = $.NSImage.alloc.initWithSize($.NSMakeSize(size, size));
	canvas.lockFocus;
	$.NSGraphicsContext.currentContext.imageInterpolation = $.NSImageInterpolationHigh;
	var rect = $.NSMakeRect(0, 0, size, size);
	$.NSBezierPath.bezierPathWithRoundedRectXRadiusYRadius(rect, 224, 224).addClip;
	src.drawInRectFromRectOperationFraction(rect, $.NSZeroRect, $.NSCompositingOperationSourceOver, 1.0);
	var outRep = $.NSBitmapImageRep.alloc.initWithFocusedViewRect(rect);
	canvas.unlockFocus;
	var data = outRep.representationUsingTypeProperties($.NSBitmapImageFileTypePNG, $({}));
	data.writeToFileAtomically(p, true);
}
JXA
}

install_original_icon() {
	local out="$APP/Contents/Resources/MirrorsEdge.icns"
	command -v sips >/dev/null 2>&1 && command -v iconutil >/dev/null 2>&1 || {
		[ -n "$EXISTING_ICNS" ] && [ -f "$EXISTING_ICNS" ] && cp "$EXISTING_ICNS" "$out" && ok "Preserved app icon"
		return 0
	}
	local ico="" src_label="" exe=""
	ico="$(find -H "$ASSET_SRC" -maxdepth 2 -iname 'ME_Icon.ico' -print -quit 2>/dev/null || true)"
	[ -n "$ico" ] || ico="$(find -H "$ASSET_SRC" -maxdepth 2 -iname 'goggame-*.ico' -print -quit 2>/dev/null || true)"
	if [ -z "$ico" ] && [ -n "$GOG_EXTRACT_DIR" ]; then
		ico="$(find -H "$GOG_EXTRACT_DIR" -maxdepth 3 \( -iname 'ME_Icon.ico' -o -iname 'goggame-*.ico' \) -print -quit 2>/dev/null || true)"
	fi
	if [ -z "$ico" ] && [ -n "$EXISTING_ICNS" ] && [ -f "$EXISTING_ICNS" ]; then
		cp "$EXISTING_ICNS" "$out"
		ok "Preserved existing game icon"
		return 0
	fi
	if [ -n "$ico" ] && [ -f "$ico" ]; then
		src_label="$(basename "$ico")"
	else
		exe="$(find_ci_file "$SRC_BIN" "mirrorsedge.exe" || true)"
		if [ -n "$exe" ] && extract_pe_icon "$exe" "$TMP/me_pe.ico"; then
			ico="$TMP/me_pe.ico"
			src_label="$(basename "$exe")"
		fi
	fi
	[ -f "$ico" ] || return 0

	local base="$TMP/orig_icon.png" setdir="$TMP/MirrorsEdge.iconset"
	sips -s format png "$ico" --out "$base" >/dev/null 2>&1 || return 0
	shape_macos_icon "$base"
	rm -rf "$setdir"
	mkdir -p "$setdir"
	sips -z 16 16     "$base" --out "$setdir/icon_16x16.png" >/dev/null 2>&1 || return 0
	sips -z 32 32     "$base" --out "$setdir/icon_16x16@2x.png" >/dev/null 2>&1 || return 0
	cp                "$setdir/icon_16x16@2x.png" "$setdir/icon_32x32.png"
	sips -z 64 64     "$base" --out "$setdir/icon_32x32@2x.png" >/dev/null 2>&1 || return 0
	sips -z 128 128   "$base" --out "$setdir/icon_128x128.png" >/dev/null 2>&1 || return 0
	sips -z 256 256   "$base" --out "$setdir/icon_128x128@2x.png" >/dev/null 2>&1 || return 0
	cp                "$setdir/icon_128x128@2x.png" "$setdir/icon_256x256.png"
	sips -z 512 512   "$base" --out "$setdir/icon_256x256@2x.png" >/dev/null 2>&1 || return 0
	cp                "$setdir/icon_256x256@2x.png" "$setdir/icon_512x512.png"
	sips -z 1024 1024 "$base" --out "$setdir/icon_512x512@2x.png" >/dev/null 2>&1 || return 0
	iconutil -c icns "$setdir" -o "$out" >/dev/null 2>&1 && ok "Applied original game icon ($src_label)" || true
}
install_original_icon

python3 - "$APP/Contents/Info.plist" "$APP_NAME" <<'PY'
import plistlib, sys
path, name = sys.argv[1], sys.argv[2]
with open(path, "rb") as f:
    plist = plistlib.load(f)
plist["CFBundleName"] = name
plist["CFBundleDisplayName"] = name
plist["CFBundleIconFile"] = "MirrorsEdge"
with open(path, "wb") as f:
    plistlib.dump(plist, f)
PY
shasum -a 256 "$APP/Contents/MacOS/RunnerMetal" | awk '{print $1}' > "$APP/Contents/Resources/version.sha"

sign_bundle() {
	xattr -cr "$APP" 2>/dev/null || true
	if [ -f "$APP/Contents/Frameworks/libSDL3.0.dylib" ]; then
		codesign --force --sign - "$APP/Contents/Frameworks/libSDL3.0.dylib" >/dev/null 2>&1 || return 1
	fi
	if [ -f "$APP/Contents/Frameworks/libGameLifted.dylib" ]; then
		codesign --force --sign - "$APP/Contents/Frameworks/libGameLifted.dylib" >/dev/null 2>&1 || return 1
	fi
	codesign --force --sign - "$APP/Contents/MacOS/RunnerMetal" >/dev/null 2>&1 || return 1
	codesign --force --sign - "$APP" >/dev/null 2>&1 || return 1
	codesign --verify "$APP" >/dev/null 2>&1 || return 1
}
run_task "Ad-hoc signing app bundle" sign_bundle || die "codesign failed"

# ---------------------------------------------------------------------------
# Step 5: Install / update in-place or wrap into DMG.
# ---------------------------------------------------------------------------
outro() {
	printf '\n'
	printf '%s✔ Done!%s %s\n' "$GREEN$BOLD" "$RESET" "$1"
	printf '  %s\n' "$2"
	printf "  Saves, configs, and shader cache live in: ~/Library/Application Support/Mirror's Edge Native\n"
	printf '  macOS Game Mode activates automatically while playing.\n'
	printf '\n'
	printf '       %sfinished in %dm %02ds%s\n' "$DIM" $((SECONDS / 60)) $((SECONDS % 60)) "$RESET"
	printf '\n'
}

if [ "$WANT_DMG" = no ]; then
	if [ -n "$EXISTING_APP" ]; then
		INSTALL_DIR="$(dirname "$EXISTING_APP")"
		step "Updating existing $EXISTING_APP"
		STAGED_NEW="$INSTALL_DIR/.${APP_NAME}.app.new.$$"
		BACKUP_OLD="$INSTALL_DIR/.${APP_NAME}.app.old.$$"
		if [ -w "$INSTALL_DIR" ] && [ ! -e "$EXISTING_APP" -o -w "$EXISTING_APP" ]; then
			rm -rf "$STAGED_NEW" "$BACKUP_OLD"
			mv "$APP" "$STAGED_NEW"
			mv "$EXISTING_APP" "$BACKUP_OLD"
			mv "$STAGED_NEW" "$EXISTING_APP"
			rm -rf "$BACKUP_OLD"
		else
			warn "$INSTALL_DIR is not writable; placing updated app in $DEST_DIR instead"
			mkdir -p "$DEST_DIR"
			rm -rf "$DEST_DIR/$APP_NAME.app"
			mv "$APP" "$DEST_DIR/$APP_NAME.app"
			EXISTING_APP="$DEST_DIR/$APP_NAME.app"
		fi
		/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister -f "$EXISTING_APP" >/dev/null 2>&1 || true
		ok "Updated $EXISTING_APP"
		outro "$EXISTING_APP has been updated." "Double-click it to launch (saves and settings preserved)."
		[ "$FANCY" = yes ] && open -R "$EXISTING_APP" >/dev/null 2>&1 || true
		exit 0
	fi

	mkdir -p "$DEST_DIR"
	step "Installing to $DEST_DIR"
	rm -rf "$DEST_DIR/$APP_NAME.app"
	mv "$APP" "$DEST_DIR/$APP_NAME.app"
	/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister -f "$DEST_DIR/$APP_NAME.app" >/dev/null 2>&1 || true
	ok "Placed $APP_NAME.app in $DEST_DIR"
	outro "$DEST_DIR/$APP_NAME.app is ready." "Drag it into /Applications (or double-click it directly) to play."
	[ "$FANCY" = yes ] && open -R "$DEST_DIR/$APP_NAME.app" >/dev/null 2>&1 || true
	exit 0
fi

mkdir -p "$DEST_DIR"
step "Building disk image"
STAGE="$TMP/stage"
mkdir -p "$STAGE"
mv "$APP" "$STAGE/$APP_NAME.app"
ln -s /Applications "$STAGE/Applications"
TMPDMG="$TMP/rw.dmg"
dmg_create() { hdiutil create -srcfolder "$STAGE" -volname "$VOLNAME" -fs HFS+ -format UDRW "$TMPDMG" >/dev/null; }
run_task "Creating disk image" dmg_create || die "hdiutil create failed"
DEV=$(hdiutil attach -readwrite -noverify -noautoopen "$TMPDMG" | grep -E '^/dev/' | awk 'NR==1{print $1}')

osascript >/dev/null 2>&1 <<APPLESCRIPT || true
tell application "Finder"
  tell disk "$VOLNAME"
    open
    set current view of container window to icon view
    set toolbar visible of container window to false
    set statusbar visible of container window to false
    set the bounds of container window to {400, 100, 900, 430}
    set theViewOptions to the icon view options of container window
    set arrangement of theViewOptions to not arranged
    set icon size of theViewOptions to 128
    set position of item "$APP_NAME.app" of container window to {130, 165}
    set position of item "Applications" of container window to {370, 165}
    update without registering applications
    delay 1
    close
  end tell
end tell
APPLESCRIPT

sync
hdiutil detach "$DEV" >/dev/null; DEV=""
rm -f "$DEST_DIR/$APP_NAME.dmg"
dmg_convert() { hdiutil convert "$TMPDMG" -format UDZO -imagekey zlib-level=9 -o "$DEST_DIR/$APP_NAME.dmg" >/dev/null; }
run_task "Compressing disk image" dmg_convert || die "hdiutil convert failed"
ok "Created $DEST_DIR/$APP_NAME.dmg"
outro "$DEST_DIR/$APP_NAME.dmg is ready." "Opening it now — drag Mirror's Edge.app into Applications to install."
[ "$FANCY" = yes ] && open "$DEST_DIR/$APP_NAME.dmg" >/dev/null 2>&1 || true
